(async () => {
  const site = (await (await fetch('snapshot/site.json')).json()).profile.site;
  if (site.front_door !== 'desktop') throw new Error(`this build's front door is ${site.front_door}`);
  const by = site.name;
  if (document.title !== `${site.title} — ${by}`) throw new Error(`title: ${document.title}`);
  const crumb = document.querySelector('header').innerText;
  if (!crumb.includes(site.title)) throw new Error(`the menu bar does not name the site: ${crumb}`);
  const icon = document.querySelector("link[rel='icon']").getAttribute('href');
  if (!icon.endsWith(site.mark)) throw new Error(`tab icon: ${icon}`);
  const mark = document.querySelector('header img');
  if (!mark || !mark.src.endsWith(site.mark) || !mark.naturalWidth) throw new Error('the mark is not drawn in the menu bar');
  return { title: document.title, mark: site.mark };
})()

(async () => {
  const doc = await (await fetch('snapshot/apps.json')).json();
  const site = (await (await fetch('snapshot/site.json')).json()).profile.site;
  const labels = [...document.querySelectorAll("nav[aria-label='Apps'] button, nav[aria-label='Apps'] a")].map((b) => b.innerText.trim());
  const missing = doc.repos.map((r) => r.name).filter((n) => !labels.includes(n));
  if (missing.length) throw new Error(`no icon for: ${missing.join(', ')}`);
  if (labels.length !== doc.repos.length + 3) throw new Error(`${labels.length} icons for ${doc.repos.length} repos`);
  const first = doc.repos.find((r) => r.id === site.desktop.pinned[0]).name;
  if (labels[0] !== first) throw new Error(`the first icon is ${labels[0]}, not the pinned ${first}`);
  for (const tail of ['Fleet', 'Profile', 'Console']) if (!labels.slice(-3).includes(tail)) throw new Error(`no ${tail} icon`);
  return { icons: labels.length, repos: doc.repos.length, first };
})()

(async () => {
  const site = (await (await fetch('snapshot/site.json')).json()).profile.site;
  const doc = await (await fetch('snapshot/apps.json')).json();
  const app = doc.apps.find((a) => a.id === site.desktop.pinned[0]);
  const live = new URL(app.targets.find((t) => t.kind === 'live').url);
  const policy = document.querySelector("meta[http-equiv='Content-Security-Policy']").content;
  const frames = /frame-src ([^;]*)/.exec(policy)[1].split(' ');
  if (!frames.includes(live.origin)) throw new Error(`frame-src does not admit ${live.origin}`);
  if (frames.some((f) => f === '*' || f === 'https:' || f === 'http:')) throw new Error(`frame-src has a wildcard: ${frames}`);
  sessionStorage.setItem('verify_live', live.href);
  [...document.querySelectorAll("nav[aria-label='Apps'] button")].find((b) => b.innerText.trim() === app.name).click();
  return { app: app.id, live: live.href, admitted: frames.length };
})()

(() => {
  const frame = document.querySelector("iframe[title$='— Live']");
  if (frame.src !== sessionStorage.getItem('verify_live')) throw new Error(`framed ${frame.src}`);
  const sandbox = frame.getAttribute('sandbox');
  if (sandbox.includes('allow-top-navigation')) throw new Error('a framed app could take the tab');
  return { src: frame.src, same_origin_kept: sandbox.includes('allow-same-origin') };
})()

(() => {
  const icon = [...document.querySelectorAll("nav[aria-label='Apps'] button, nav[aria-label='Apps'] a")].find((b) => b.innerText.trim() === 'Profile');
  const how = icon.tagName === 'A' ? `link to ${icon.getAttribute('href')}` : 'window';
  icon.click();
  return how;
})()

(async () => {
  const name = (await (await fetch(`${document.baseURI.replace(/[^/]*$/, '')}snapshot/site.json`.replace(/\/home\/snapshot/, '/snapshot'))).json()).profile.name;
  for (let i = 0; i < 40; i += 1) {
    const frame = document.querySelector("iframe[title='Console page /home']");
    const text = frame ? frame.contentDocument?.body?.innerText ?? '' : (location.pathname.replace(/\/$/, '').endsWith('/home') ? document.body.innerText : '');
    if (text.includes(name)) return { where: frame ? 'a window on the desktop' : location.pathname, name };
    await new Promise((r) => setTimeout(r, 250));
  }
  throw new Error('the profile did not open at /home');
})()

(async () => {
  const site = (await (await fetch(new URL('../snapshot/site.json', location.href))).json()).profile.site;
  const brand = document.querySelector("header a[href]");
  for (let i = 0; i < 20 && !brand.innerText.includes(site.title); i += 1) await new Promise((r) => setTimeout(r, 250));
  if (!brand.innerText.includes(site.title)) throw new Error(`the header says: ${brand.innerText}`);
  if (!brand.querySelector('img').src.endsWith(site.mark)) throw new Error('the header mark is not the site\'s');
  if (new URL(brand.href).pathname !== new URL('../', location.href).pathname) throw new Error(`the brand leads to ${brand.href}`);
  return { brand: brand.innerText.replace(/\n/g, ' '), leads_to: new URL(brand.href).pathname };
})()

